const { jsPDF } = window.jspdf;

// ფონტის დამატება
jsPDF.API.events.push("addFonts", function () {
    this.addFileToVFS("FiraGO.ttf", ""); // აქ ჩასვით ფონტის Base64 კოდი
    this.addFont("FiraGO.ttf", "FiraGO", "normal");
});

function validateForm() {
    const form = document.getElementById("cvForm");
    if (!form.checkValidity()) {
        alert("გთხოვთ, შეავსოთ ყველა სავალდებულო ველი.");
        return false;
    }
    return true;
}

function generatePDF() {
    if (!validateForm()) return;

    const doc = new jsPDF();

    // ფონტის და ტექსტის ზომის დაყენება
    doc.setFont("FiraGO", "normal");
    doc.setFontSize(12);

    // გვერდის ფონის ფერი
    doc.setFillColor(240, 240, 240); // ღია ნაცრისფერი
    doc.rect(0, 0, 210, 297, 'F');

    // ფოტოს ჩასმა (თუ არის ატვირთული)
    const photo = document.getElementById('photo'); // ფოტოს input ელემენტი
    if (photo && photo.files.length > 0) {
        const reader = new FileReader();
        reader.onload = function(event) {
            doc.addImage(event.target.result, 'JPEG', 10, 10, 30, 30); // ფოტო მარცხენა ზედა კუთხეში
            renderText(doc); // ტექსტის რენდერი
            doc.save("CV.pdf");
        };
        reader.readAsDataURL(photo.files[0]);
    } else {
        // თუ ფოტო არ არის
        renderText(doc); // ტექსტის რენდერი
        doc.save("CV.pdf");
    }
}

function renderText(doc) {
    // ტექსტის განლაგება
    const name = document.getElementById('name').value || 'სახელი გვარი';
    const email = document.getElementById('email').value || 'email@example.com';
    const position = document.getElementById('position').value || 'პოზიცია';
    const education = document.getElementById('education').value || 'განათლება';
    const experience = document.getElementById('experience').value || 'გამოცდილება';
    const skills = document.getElementById('skills').value || 'უნარები';
    const social = document.getElementById('social').value || 'სოციალური ქსელები';

    // სათაური
    doc.setTextColor(33, 37, 41); // მუქი ნაცრისფერი
    doc.setFontSize(18);
    doc.text("Სივი", 105, 20, { align: "center" });

    // ძირითადი ინფორმაცია
    doc.setFontSize(12);
    doc.setTextColor(0, 0, 0); // შავი
    doc.text(`სახელი, გვარი: ${name}`, 50, 50);
    doc.text(`ელფოსტა: ${email}`, 50, 60);
    doc.text(`პოზიცია: ${position}`, 50, 70);

    // განათლება
    doc.setTextColor(33, 37, 41); // მუქი ნაცრისფერი
    doc.setFontSize(14);
    doc.text("განათლება:", 50, 90);
    doc.setFontSize(12);
    doc.setTextColor(0, 0, 0);
    doc.text(education, 50, 100);

    // გამოცდილება
    doc.setTextColor(33, 37, 41);
    doc.setFontSize(14);
    doc.text("გამოცდილება:", 50, 120);
    doc.setFontSize(12);
    doc.setTextColor(0, 0, 0);
    doc.text(experience, 50, 130);

    // უნარები
    doc.setTextColor(33, 37, 41);
    doc.setFontSize(14);
    doc.text("უნარები და ენები:", 50, 150);
    doc.setFontSize(12);
    doc.setTextColor(0, 0, 0);
    doc.text(skills, 50, 160);

    // სოციალური ქსელები
    doc.setTextColor(33, 37, 41);
    doc.setFontSize(14);
    doc.text("სოციალური ქსელები:", 50, 180);
    doc.setFontSize(12);
    doc.setTextColor(0, 0, 0);
    doc.text(social, 50, 190);
}
